// #Sireum

package factory_dispatch_coordinator.Factory_Dispatch_Coordinator

import org.sireum._
import art._
import factory_dispatch_coordinator._

// Do not edit this file as it will be overwritten if HAMR codegen is rerun

@sig trait Request_Qualification_Api {
  def id: Art.BridgeId
  def request_arrival_Id : Art.PortId
  def arrival_fact_Id : Art.PortId

  // Logika spec var representing port state for outgoing data port
  @spec var arrival_fact: Factory_Dispatch_Coordinator.Arrival_Fact.Type = $

  def put_arrival_fact(value : Factory_Dispatch_Coordinator.Arrival_Fact.Type) : Unit = {
    Contract(
      Modifies(arrival_fact),
      Ensures(
        arrival_fact == value
      )
    )
    Spec {
      arrival_fact = value
    }

    Art.putValue(arrival_fact_Id, Factory_Dispatch_Coordinator.Arrival_Fact_Payload(value))
  }

  def logInfo(msg: String): Unit = {
    Art.logInfo(id, msg)
  }

  def logDebug(msg: String): Unit = {
    Art.logDebug(id, msg)
  }

  def logError(msg: String): Unit = {
    Art.logError(id, msg)
  }
}

@datatype class Request_Qualification_Initialization_Api (
  val id: Art.BridgeId,
  val request_arrival_Id : Art.PortId,
  val arrival_fact_Id : Art.PortId) extends Request_Qualification_Api

@datatype class Request_Qualification_Operational_Api (
  val id: Art.BridgeId,
  val request_arrival_Id : Art.PortId,
  val arrival_fact_Id : Art.PortId) extends Request_Qualification_Api {

  // Logika spec var representing port state for incoming data port
  @spec var request_arrival: Factory_Dispatch_Coordinator.Request_Arrival_Sample.Type = $

  def get_request_arrival() : Option[Factory_Dispatch_Coordinator.Request_Arrival_Sample.Type] = {
    Contract(
      Ensures(
        Res == Some(request_arrival)
      )
    )
    val value : Option[Factory_Dispatch_Coordinator.Request_Arrival_Sample.Type] = Art.getValue(request_arrival_Id) match {
      case Some(Factory_Dispatch_Coordinator.Request_Arrival_Sample_Payload(v)) => Some(v)
      case Some(v) =>
        Art.logError(id, s"Unexpected payload on port request_arrival.  Expecting 'Factory_Dispatch_Coordinator.Request_Arrival_Sample_Payload' but received ${v}")
        None[Factory_Dispatch_Coordinator.Request_Arrival_Sample.Type]()
      case _ => None[Factory_Dispatch_Coordinator.Request_Arrival_Sample.Type]()
    }
    return value
  }
}
